def investigate(context, acquire):
    history = acquire("history")

    def simulate_put(state, key, value, strategy):
        if strategy == "ignore":
            if key not in state:
                return dict(state, **{key: value}), 1
            else:
                return state, 0
        elif strategy == "replace":
            new_state = dict(state)
            new_state[key] = value
            return new_state, 1
        elif strategy == "upsert":
            new_state = dict(state)
            new_state[key] = value
            return new_state, 1
        return state, 0

    def apply_op(store, op, k, v, s_type):
        if op == "put":
            return simulate_put(store, k, v, s_type)
        elif op == "update":
            if k in store:
                new_store = dict(store)
                new_store[k] = v
                return new_store, 1
            else:
                return store, 0
        elif op == "delete":
            if k in store:
                new_store = dict(store)
                del new_store[k]
                return new_store, 1
            else:
                return store, 0
        return store, 0

    strategies = ["ignore", "replace", "upsert"]
    valid_strategies = []

    for strat in strategies:
        match_all = True
        for receipt in history:
            acts = receipt.get("actions", [])
            obs = receipt.get("observed", {})
            exp_count = obs.get("committed_count")
            exp_sum = obs.get("committed_sum")

            if exp_count is None or exp_sum is None:
                continue

            global_db = {}
            txn_active = False
            txn_owner = None
            txn_buffer = None
            sim_ok = True

            for act in acts:
                op = act.get("op")
                conn = act.get("connection", "main")
                k = act.get("key")
                v = act.get("value")

                if op == "begin":
                    if txn_active:
                        sim_ok = False; break
                    txn_active = True
                    txn_owner = conn
                    txn_buffer = dict(global_db)
                elif op == "commit":
                    if not txn_active:
                         sim_ok = False; break
                    txn_active = False
                    txn_owner = None
                    txn_buffer = None
                elif op == "rollback":
                    if not txn_active:
                         sim_ok = False; break
                    global_db = txn_buffer
                    txn_active = False
                    txn_owner = None
                    txn_buffer = None
                else:
                    updated_store, _ = apply_op(global_db, op, k, v, strat)
                    global_db = updated_store

            if not sim_ok:
                match_all = False
                break

            calc_count = len(global_db)
            calc_sum = sum(global_db.values())

            if calc_count != exp_count or calc_sum != exp_sum:
                match_all = False
                break

        if match_all:
            valid_strategies.append(strat)

    if len(valid_strategies) != 1:
        return {"value": None, "unresolved": True}

    confirmed_strategy = valid_strategies[0]

    channel_candidates = ["main_changes", "main_total", "combined_total"]
    valid_channels = []

    for ch_type in channel_candidates:
        match_all_ch = True
        for receipt in history:
            acts = receipt.get("actions", [])
            obs = receipt.get("observed", {})
            exp_channel = obs.get("channel")

            if exp_channel is None:
                continue

            global_db = {}
            txn_active = False
            txn_owner = None
            txn_buffer = None
            main_changes_last = 0
            main_total_cumulative = 0
            other_total_cumulative = 0
            sim_err = False

            for act in acts:
                op = act.get("op")
                conn = act.get("connection", "main")
                k = act.get("key")
                v = act.get("value")
                stmt_rows_affected = 0

                if op == "begin":
                    if txn_active:
                        sim_err = True; break
                    txn_active = True
                    txn_owner = conn
                    txn_buffer = dict(global_db)
                    stmt_rows_affected = 0
                elif op == "commit":
                    if not txn_active:
                         sim_err = True; break
                    txn_active = False
                    txn_owner = None
                    txn_buffer = None
                    stmt_rows_affected = 0
                elif op == "rollback":
                    if not txn_active:
                         sim_err = True; break
                    global_db = txn_buffer
                    txn_active = False
                    txn_owner = None
                    txn_buffer = None
                    stmt_rows_affected = 0
                else:
                    _, rows = apply_op(global_db, op, k, v, confirmed_strategy)
                    stmt_rows_affected = rows
                    if conn == "main":
                        main_changes_last = stmt_rows_affected
                        main_total_cumulative += stmt_rows_affected
                    else:
                        other_total_cumulative += stmt_rows_affected

            if sim_err:
                match_all_ch = False
                break

