def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_op, channel_type, trigger):
        committed = {}
        main_tx = None
        other_tx = None
        total_changes_main = 0
        total_changes_other = 0
        last_changes_main = 0

        def get_effective(conn):
            if conn == 'main':
                tx = main_tx
            else:
                tx = other_tx
            if tx is None:
                return dict(committed)
            eff = dict(committed)
            for k, v in tx.items():
                if v is None:
                    if k in eff:
                        del eff[k]
                else:
                    eff[k] = v
            return eff

        def apply_put(conn, key, value):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            exists = key in eff
            changes = 0
            if put_op == 'ignore':
                if not exists:
                    changes = 1
                    if conn == 'main':
                        if main_tx is not None:
                            main_tx[key] = value
                        else:
                            committed[key] = value
                    else:
                        if other_tx is not None:
                            other_tx[key] = value
                        else:
                            committed[key] = value
            elif put_op == 'replace':
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            elif put_op == 'upsert':
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes
            if trigger and changes > 0:
                if conn == 'main':
                    total_changes_main += 1
                else:
                    total_changes_other += 1

        def apply_update(conn, key, value):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            if key in eff:
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = value
                    else:
                        committed[key] = value
                else:
                    if other_tx is not None:
                        other_tx[key] = value
                    else:
                        committed[key] = value
            else:
                changes = 0
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes

        def apply_delete(conn, key):
            nonlocal committed, main_tx, other_tx, total_changes_main, total_changes_other, last_changes_main
            eff = get_effective(conn)
            if key in eff:
                changes = 1
                if conn == 'main':
                    if main_tx is not None:
                        main_tx[key] = None
                    else:
                        if key in committed:
                            del committed[key]
                else:
                    if other_tx is not None:
                        other_tx[key] = None
                    else:
                        if key in committed:
                            del committed[key]
            else:
                changes = 0
            if conn == 'main':
                total_changes_main += changes
                last_changes_main = changes
            else:
                total_changes_other += changes

        for action in actions:
